-- Mensagens dos checkpoints: todas no formato da de 6 meses, com versões 1, 2 e 3 (para não repetir
-- a mesma mensagem ao mesmo doador) e tratamento masculino/feminino. Versões 2 e 3 começam em branco.
alter table modelos_mensagem add column if not exists variacoes jsonb;
-- Tratamento do doador (o/a), escolhido pelo membro na ficha e lembrado para os próximos contatos.
alter table relacionamento add column if not exists tratamento text check (tratamento in ('m', 'f'));
-- Versão da mensagem usada no contato.
alter table contatos add column if not exists versao smallint check (versao between 1 and 3);

update modelos_mensagem set variacoes = '{"1": {"m": [{"rotulo": "Saudação e apresentação", "texto": "{saudacao}, {nome}, tudo bem? Me chamo Rafael e sou o diretor de captação do CASD."}, {"rotulo": "Agradecimento", "texto": "Hoje, nós temos a alegria de receber você como novo doador do curso! Sem pessoas como você, não conseguiríamos transformar as mais de 900 vidas que nós atendemos. Muito obrigado por acreditar em nosso trabalho e fazer parte da família CASD!"}, {"rotulo": "O Plano de Doadores", "texto": "A gente tem um Plano de Doadores pra quem apoia todo mês: em alguns momentos da sua caminhada com o CASD (na primeira renovação, aos 6 meses, quando completar 1 ano e depois a cada 6 meses), eu te mando notícias dos alunos e um agradecimento especial. Em alguns desses momentos tem até um presente 🎁"}, {"rotulo": "Como vamos falar com você", "texto": "Fora isso, só te procuro se acontecer algum problema com o pagamento, pra te ajudar a resolver. As novidades gerais do cursinho vão pela nossa newsletter, por e-mail."}, {"rotulo": "Pergunta", "texto": "Posso te incluir no Plano? E pra você é melhor receber por aqui ou por e-mail?"}], "f": [{"rotulo": "Saudação e apresentação", "texto": "{saudacao}, {nome}, tudo bem? Me chamo Rafael e sou o diretor de captação do CASD."}, {"rotulo": "Agradecimento", "texto": "Hoje, nós temos a alegria de receber você como nova doadora do curso! Sem pessoas como você, não conseguiríamos transformar as mais de 900 vidas que nós atendemos. Muito obrigado por acreditar em nosso trabalho e fazer parte da família CASD!"}, {"rotulo": "O Plano de Doadores", "texto": "A gente tem um Plano de Doadores pra quem apoia todo mês: em alguns momentos da sua caminhada com o CASD (na primeira renovação, aos 6 meses, quando completar 1 ano e depois a cada 6 meses), eu te mando notícias dos alunos e um agradecimento especial. Em alguns desses momentos tem até um presente 🎁"}, {"rotulo": "Como vamos falar com você", "texto": "Fora isso, só te procuro se