update modelos_mensagem set texto = (select string_agg(p->>'texto', E'\n\n' order by i) from jsonb_array_elements(partes) with ordinality as t(p, i))
where chave in ('boas_vindas', 'renovacao_1', 'meses_6', 'ano_1', 'semestral');
